      "evidence": ["src/pyreadline3/lineeditor/history.py", "src/pyreadline3/rlmain.py"]
    },
    {
      "name": "自动补全",
      "description": "实现 GNU readline 的 Tab 补全机制（completer / completer_delims / get_begidx / get_endidx），可与 Python 标准库 rlcompleter 无缝配合，支持文件名补全和自定义补全器。",
      "evidence": ["src/pyreadline3/rlmain.py", "src/pyreadline3/modes/basemode.py"]
    },
    {
      "name": "按键绑定与编辑模式",
      "description": "提供 Emacs 和 Vi 两种编辑模式，支持按键绑定（parse_and_bind），预定义了大量 readline 标准快捷键（如 Ctrl-A/E/N/P/F/B/D/K/U/W 等），也支持用户自定义绑定。",
